def findMaximumNum(str, k):
    def helper(s, k):
        if k == 0:
            return s
        n = len(s)
        max_str = s
        for i in range(n):
            for j in range(i + 1, n):
                if s[i] < s[j]:
                    new_s = s[:i] + s[j] + s[i+1:j] + s[i] + s[j+1:]
                    max_str = max(max_str, helper(new_s, k - 1))
        return max_str

    return helper(str, k)

